package com.vandorlabs.neoforge;
import com.mojang.blaze3d.vertex.PoseStack;
import com.vandorlabs.neoforge.programmer.NativeProgrammerAssets;
import com.vandorlabs.neoforge.programmer.client.*;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.*;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.client.resources.model.*;
import net.minecraft.core.Direction;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.RandomSource;
import net.minecraft.world.item.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;
import net.neoforged.neoforge.client.model.data.ModelData;
/** Actual complete-OBJ item submission, independent of canonical item registration. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class ProgrammerItemRenderChecks {
 private static final class Gallery extends Screen{Gallery(){super(net.minecraft.network.chat.Component.literal("Programmer item"));}@Override public void render(net.minecraft.client.gui.GuiGraphics gui,int x,int y,float partial){}}
 private static NativeProgrammerItemModel model,prior;private static int generation,frames,checks;private static boolean capture,done;private static java.util.concurrent.CompletableFuture<Void> reload;private static final ItemStack[] icons=new ItemStack[16];
 private static boolean active(){return Boolean.getBoolean("vandorlabs.programmerItemCheck");}
 private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Programmer item generation="+generation+": "+why);}
 private static void dynamic(Minecraft mc){String id=NativeProgrammerAssets.item();var key=ModelResourceLocation.standalone(ResourceLocation.parse(id));var original=mc.getModelManager().getModel(key);int[] calls={0};var source=new net.neoforged.neoforge.client.model.BakedModelWrapper<BakedModel>(original){@Override public java.util.List<net.minecraft.client.renderer.block.model.BakedQuad> getQuads(net.minecraft.world.level.block.state.BlockState state,Direction side,RandomSource random,ModelData data,net.minecraft.client.renderer.RenderType layer){if(side!=null)return List.of();var base=original.getQuads(state,null,RandomSource.create(0),data,layer).getFirst();int[] raw=base.getVertices(),values=new int[48];for(int v=0;v<4;v++){System.arraycopy(raw,v*raw.length/4,values,v*12,8);for(int n=8;n<12;n++)values[v*12+n]=0x12340000+v*16+n;}values[0]=Float.floatToRawIntBits(Float.intBitsToFloat(values[0])+(++calls[0]%2)*.03125F);return List.of(new net.minecraft.client.renderer.block.model.BakedQuad(values,base.getTintIndex(),base.getDirection(),base.getSprite(),base.isShade(),base.hasAmbientOcclusion()));}};var models=new HashMap<ModelResourceLocation,BakedModel>();for(String model:NativeProgrammerAssets.models()){var location=ModelResourceLocation.standalone(ResourceLocation.parse(model));models.put(location,mc.getModelManager().getModel(location));}models.put(key,source);var bake=new NativeProgrammerBake(models,m->mc.getTextureAtlas(m.atlasLocation()).apply(m.texture()),mc.getResourceManager());var wrapped=new NativeProgrammerItemModel(bake);var first=wrapped.getQuads(null,null,null,ModelData.EMPTY,null);var second=wrapped.getQuads(null,null,null,ModelData.EMPTY,null);need(first.getFirst().getVertices()[0]!=second.getFirst().getVertices()[0],"dynamic item source remains live");for(var quad:second)for(int v=0;v<4;v++)for(int n=8;n<12;n++)need(quad.getVertices()[v*12+n]==0x12340000+v*16+n,"extended item payload survives normalization");}
 private static void prepare(){var mc=Minecraft.getInstance();dynamic(mc);var bake=NativeProgrammerResources.currentBake();need(bake!=null,"actual completed atlas generation");model=new NativeProgrammerItemModel(bake);need(model!=prior,"wrapper rebuilt on resource reload");prior=model;var quads=model.getQuads(null,null,null,ModelData.EMPTY,null);need(quads.size()==(generation==2?6:108),"released or pack-authored complete item");need(!NativeItemPadding.needsFit(model,model.getTransforms()),"rotated item has visible GUI padding");for(var quad:quads)need(!quad.getSprite().contents().name().getPath().equals("missingno"),"actual authored sprite");for(int i=0;i<icons.length;i++){icons[i]=new ItemStack(Items.STONE);var tag=new net.minecraft.nbt.CompoundTag();tag.putString("PrivateProgrammer","opaque"+i);icons[i].set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(tag));}for(int i=0;i<12000;i++){need(model.getQuads(null,null,null,ModelData.EMPTY,null)==quads,"immutable prepared quads");model.getRenderPasses(icons[i%16],false);}var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId(),before=meter.getThreadAllocatedBytes(thread);for(int i=0;i<10000;i++){model.getQuads(null,null,null,ModelData.EMPTY,null);model.getRenderPasses(icons[i%16],false);}long bytes=meter.getThreadAllocatedBytes(thread)-before;need(bytes<=128,"warm item allocated="+bytes);need(model.retainedBytes()<128*1024,"bounded item retained bytes");System.out.println("[vandorlabs][programmer-item-render] generation="+generation+" quads="+quads.size()+" retained="+model.retainedBytes()+" warm10000="+bytes);}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!active()||done)return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(event.getScreen() instanceof AccessibilityOnboardingScreen intro){intro.onClose();return;}if(event.getScreen() instanceof TitleScreen){mc.getWindow().setWindowed(1280,720);mc.options.guiScale().set(2);mc.resizeDisplay();mc.setScreen(new Gallery());return;}if(!(event.getScreen() instanceof Gallery))return;if(reload!=null){if(!reload.isDone())return;reload.join();reload=null;}if(model==null)prepare();var gui=event.getGuiGraphics();gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);if(frames>=4){com.mojang.blaze3d.platform.Lighting.setupFor3DItems();var buffers=mc.renderBuffers().bufferSource();for(int i=0;i<16;i++){var poses=gui.pose();poses.pushPose();try{poses.translate(48+(i%4)*32,48+(i/4)*32,200);poses.scale(16,-16,16);mc.getItemRenderer().render(icons[i],ItemDisplayContext.GUI,false,poses,buffers,0xF000F0,OverlayTexture.NO_OVERLAY,model);}finally{poses.popPose();}}buffers.endBatch();gui.flush();}frames++;capture=frames==4||frames==9;}
 @SubscribeEvent public static void shot(RenderFrameEvent.Post event)throws Exception{if(!active()||!capture||done)return;capture=false;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){var path=mc.gameDirectory.toPath().resolve("screenshots/programmer-item-"+generation+"-"+(frames==4?"disabled":"positive")+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);double scale=mc.getWindow().getGuiScale();for(int i=0;i<16;i++){int ink=0;for(int y=0;y<16*scale;y++)for(int x=0;x<16*scale;x++){int px=(int)((40+i%4*32)*scale)+x,py=(int)((40+i/4*32)*scale)+y;if((image.getPixelRGBA(px,py)&0xffffff)!=0x302820){ink++;need(x>=1&&y>=1&&x<16*scale-1&&y<16*scale-1,"visible padding icon="+i+" pixel="+x+","+y);}}need(frames==4?ink==0:ink>100,"actual icon/disabled negative "+i+" pixels="+ink);}if(frames==9){if(generation<3){generation++;if(generation>=2){mc.getResourcePackRepository().reload();var packs=new ArrayList<>(mc.getResourcePackRepository().getSelectedIds());if(generation==2){need(mc.getResourcePackRepository().getAvailableIds().contains("file/programmer-item-replacement"),"actual replacement pack");packs.add("file/programmer-item-replacement");}else packs.remove("file/programmer-item-replacement");mc.getResourcePackRepository().setSelected(packs);}model=null;frames=0;reload=mc.reloadResourcePacks();}else{done=true;System.out.println("[vandorlabs][programmer-item-render] title PASS checks="+checks+" 16icons/padding/reload/replacement/restore/disabled/warm");mc.stop();}}}}
}
